const sources = [
  {
    name: 'glints',
    scrape_url: 'https://glints.com/id/opportunities/jobs/explore',
    base_url: 'https://glints.com'
  }
];

return sources.map(s => ({ json: s }));

// ============================================
// SMART PARSER — Extract jobs from listing page
// Builds detail_url for each job using title slug + id
// ============================================

const html = $input.first().json.data;
const sourceConfig = $('Daftar Sumber').first().json;
const baseUrl = sourceConfig.base_url || '';

const TYPE_MAP = {
  'FULL_TIME': 'full-time',
  'PART_TIME': 'part-time',
  'CONTRACT': 'contract',
  'INTERNSHIP': 'internship',
  'FREELANCE': 'freelance',
};

function slugify(text) {
  return text.toLowerCase()
    .replace(/[^a-z0-9\s-]/g, '')
    .replace(/\s+/g, '-')
    .replace(/-+/g, '-')
    .trim();
}

// ---- Glints: __NEXT_DATA__ (Next.js SSR) ----
const nextDataMatch = html.match(/<script id="__NEXT_DATA__"[^>]*>([\s\S]*?)<\/script>/);
if (nextDataMatch) {
  try {
    const data = JSON.parse(nextDataMatch[1]);
    const rawJobs = data?.props?.pageProps?.initialJobs?.jobsInPage || [];
    if (rawJobs.length > 0) {
      const jobs = rawJobs.map(job => {
        const loc = [
          job.citySubDivision?.name,
          job.city?.name,
          job.location?.name
        ].filter(Boolean);

        // Build location with city/province from parents
        const parents = job.location?.parents || [];
        const city = parents.find(p => p.level === 3)?.name;
        const province = parents.find(p => p.level === 2)?.name;
        const locationFull = [job.location?.name, city, province].filter(Boolean).join(', ');

        // Build detail URL with proper slug
        const slug = slugify(job.title);
        const detailUrl = `${baseUrl}/id/opportunities/jobs/${slug}/${job.id}`;

        // Extract skills
        const skills = (job.skills || []).map(s => s.skill?.name).filter(Boolean);

        // Extract job category
        const category = job.hierarchicalJobCategory?.parents?.[0]?.name
          || job.hierarchicalJobCategory?.name
          || null;

        return {
          _structured: true,
          title: job.title,
          company: job.company?.name || 'Tidak diketahui',
          location: locationFull || null,
          source_url: detailUrl,
          detail_url: detailUrl,
          employment_type: TYPE_MAP[job.type] || null,
          salary_min: job.salaries?.[0]?.minAmount || null,
          salary_max: job.salaries?.[0]?.maxAmount || null,
          tags: [
            category,
            ...skills.slice(0, 3)
          ].filter(Boolean),
          description_raw: null,
          source_name: sourceConfig.name,
        };
      });
      return jobs.map(j => ({ json: j }));
    }
  } catch (e) {}
}

// ---- Inertia.js / fallback ----
const inertiaMatch = html.match(/data-page="([^"]*)"/s);
if (inertiaMatch) {
  try {
    const decoded = inertiaMatch[1].replace(/&quot;/g, '"').replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&#039;/g, "'");
    const data = JSON.parse(decoded);
    const jobArray = data?.props?.jobs?.data || data?.props?.vacancies?.data || data?.props?.lowongan?.data || null;
    if (Array.isArray(jobArray) && jobArray.length > 0) {
      return jobArray.map(job => ({ json: {
        _structured: true,
        title: job.title || job.name,
        company: job.company?.name || job.company || 'Tidak diketahui',
        location: job.location || job.city || null,
        source_url: job.url ? (job.url.startsWith('http') ? job.url : baseUrl + job.url) : `${baseUrl}/lowongan/${job.slug || job.id}`,
        detail_url: null,
        employment_type: (job.type || job.employment_type || '').toLowerCase().replace(/_/g, '-') || null,
        salary_min: job.salary_min || null,
        salary_max: job.salary_max || null,
        tags: Array.isArray(job.tags) ? job.tags : (Array.isArray(job.skills) ? job.skills : []),
        description_raw: job.description || null,
        source_name: sourceConfig.name,
      }}));
    }
  } catch (e) {}
}

// ---- Fallback: chunk HTML ----
let cleaned = html.replace(/<script[\s\S]*?<\/script>/gi, '').replace(/<style[\s\S]*?<\/style>/gi, '').replace(/<nav[\s\S]*?<\/nav>/gi, '').replace(/<footer[\s\S]*?<\/footer>/gi, '').replace(/<header[\s\S]*?<\/header>/gi, '').replace(/<svg[\s\S]*?<\/svg>/gi, '').replace(/<img[^>]*>/gi, '').replace(/<!--[\s\S]*?-->/g, '').replace(/\s+/g, ' ').trim();
const CHUNK_SIZE = 3000;
const chunks = [];
for (let i = 0; i < cleaned.length; i += CHUNK_SIZE) {
  const chunk = cleaned.substring(i, i + CHUNK_SIZE);
  if (chunk.match(/job|loker|lowongan|vacancy|career|developer|manager|Rp|title|company/i)) {
    chunks.push({ _structured: false, html_chunk: chunk, source_name: sourceConfig.name, base_url: baseUrl, chunk_index: chunks.length });
  }
}
const limited = chunks.slice(0, 10);
if (limited.length === 0) throw new Error(`Tidak ada konten loker dari ${sourceConfig.name}`);
return limited.map(c => ({ json: c }));

const items = $input.all();
const sourceConfig = $('Daftar Sumber').first().json;
const baseUrl = sourceConfig.base_url || '';
const seen = new Set();
const jobs = [];

for (const item of items) {
  try {
    const content = item.json.output || '';
    let parsed = null;
    try { parsed = JSON.parse(content); } catch (e) {
      const match = content.match(/\[[\s\S]*\]/);
      if (match) try { parsed = JSON.parse(match[0]); } catch (e2) {}
    }
    if (!Array.isArray(parsed)) continue;
    for (const job of parsed) {
      if (!job.title || !job.source_path) continue;
      const sourceUrl = job.source_path.startsWith('http') ? job.source_path : baseUrl + job.source_path;
      if (seen.has(sourceUrl)) continue;
      seen.add(sourceUrl);
      let salaryMin = null, salaryMax = null;
      if (job.salary_text) {
        const nums = job.salary_text.match(/([\d.,]+)/g);
        if (nums) { const p = (s) => { let n = parseFloat(s.replace(/\./g, '').replace(',', '.')); if (job.salary_text.match(/jt|juta/i)) n *= 1e6; return Math.round(n); }; salaryMin = p(nums[0]); if (nums[1]) salaryMax = p(nums[1]); }
      }
      jobs.push({ title: job.title.trim(), company: (job.company||'?').trim(), location: job.location||null, source_url: sourceUrl, detail_url: sourceUrl, employment_type: job.employment_type||null, salary_min: salaryMin, salary_max: salaryMax, tags: Array.isArray(job.tags)?job.tags:[], description_raw: null, source_name: sourceConfig.name });
    }
  } catch (e) {}
}
if (jobs.length === 0) throw new Error('AI tidak menemukan lowongan');
return jobs.map(j => ({ json: j }));

// ============================================
// EXTRACT DETAIL DATA from detail page HTML
// Looks for JSON-LD JobPosting schema
// Falls back gracefully if detail fetch failed
// ============================================

const item = $input.first().json;
const original = $('Detail 1-by-1').first().json;

// If fetch failed or no HTML, return original data unchanged
const html = item.data || '';
if (!html || html.length < 100) {
  return [{ json: original }];
}

// Try to extract JSON-LD JobPosting
const ldMatch = html.match(/<script[^>]*type="application\/ld\+json"[^>]*>([\s\S]*?)<\/script>/i);
if (!ldMatch) {
  return [{ json: original }];
}

try {
  const ld = JSON.parse(ldMatch[1]);

  // Only process if it's a JobPosting
  if (ld['@type'] !== 'JobPosting') {
    return [{ json: original }];
  }

  // Extract description — strip HTML tags
  let description = ld.description || '';
  description = description
    .replace(/<br\s*\/?>/gi, '\n')
    .replace(/<\/p>/gi, '\n')
    .replace(/<\/li>/gi, '\n')
    .replace(/<[^>]*>/g, '')
    .replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"')
    .replace(/&#039;/g, "'")
    .replace(/\n{3,}/g, '\n\n')
    .trim();

  // Extract better location from JSON-LD
  const ldLocation = ld.jobLocation?.address;
  let location = original.location;
  if (ldLocation) {
    const parts = [
      ldLocation.addressLocality,
      ldLocation.addressRegion
    ].filter(Boolean);
    if (parts.length > 0) {
      location = parts.join(', ');
    }
  }

  // Extract salary from JSON-LD if missing
  let salaryMin = original.salary_min;
  let salaryMax = original.salary_max;
  if (!salaryMin && !salaryMax && ld.baseSalary?.value) {
    salaryMin = ld.baseSalary.value.minValue || ld.baseSalary.value.value || null;
    salaryMax = ld.baseSalary.value.maxValue || null;
  }

  // Extract expires_at
  const expiresAt = ld.validThrough || null;

  // Extract benefits as tags
  const benefits = ld.jobBenefits
    ? ld.jobBenefits.split(',').map(b => b.trim()).filter(Boolean).slice(0, 3)
    : [];

  // Merge tags (original + benefits, deduplicated)
  const allTags = [...new Set([...(original.tags || []), ...benefits])].slice(0, 6);

  return [{ json: {
    ...original,
    description_raw: description || original.description_raw,
    location: location,
    salary_min: salaryMin,
    salary_max: salaryMax,
    tags: allTags,
    expires_at: expiresAt,
  }}];

} catch (e) {
  // JSON parse failed, return original
  return [{ json: original }];
}

